// Chat-template engine vs. transformers: replays tests/ref/tmpl_fixtures
// (generated by tests/ref/tmpl_ref.py) and requires byte-identical output, or
// the same exception type and message where the reference raised.
//
//   tmpl_test [fixtures_dir] [--template NAME] [--verbose] [--bench-reps N]
//
// Also reports parse time and render time per template.
#include <algorithm>
#include <chrono>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

#include "../src/tmpl/tmpl.h"

using namespace espetero;
using Clock = std::chrono::steady_clock;

namespace {

std::string read_file(const std::string& path) {
  std::ifstream f(path, std::ios::binary);
  if (!f) {
    std::fprintf(stderr, "cannot read %s\n", path.c_str());
    std::exit(2);
  }
  std::stringstream ss;
  ss << f.rdbuf();
  return ss.str();
}

std::string show(std::string_view s, size_t max = 600) {
  std::string out;
  for (char c : s.substr(0, max)) {
    if (c == '\n')
      out += "\\n";
    else if (c == '\t')
      out += "\\t";
    else
      out.push_back(c);
  }
  if (s.size() > max) out += "...";
  return out;
}

// Where two strings first differ, with a little context.
std::string diff_at(const std::string& got, const std::string& want) {
  size_t i = 0;
  while (i < got.size() && i < want.size() && got[i] == want[i]) ++i;
  const size_t from = i > 60 ? i - 60 : 0;
  char head[64];
  std::snprintf(head, sizeof head, "first difference at byte %zu:\n", i);
  return std::string(head) + "      got: ..." + show(std::string_view(got).substr(from), 160) +
         "\n     want: ..." + show(std::string_view(want).substr(from), 160);
}

struct Outcome {
  bool ok;
  std::string text;  // output, or "Type: message"
};

// Expected output: a string (snippets) or an index into the outputs table.
std::string expected_text(const json::Value& c, const json::Value* outputs = nullptr) {
  if (const json::Value* e = c.get("error"))
    return e->get_string("type", "") + ": " + e->get_string("message", "");
  const json::Value* x = c.get("expect");
  if (x && x->is_int() && outputs) return (*outputs)[size_t(x->as_int())].as_string();
  return c.get_string("expect", "");
}

bool expects_error(const json::Value& c) { return c.get("error") != nullptr; }

// "Type: message" as Python's str(exception); compile-time errors carry an
// extra " (line N)" in what() that jinja2 keeps in a separate attribute.
std::string error_text(const tmpl::TemplateError& e) {
  std::string msg = e.what();
  if (e.line() > 0) {
    const std::string suffix = " (line " + std::to_string(e.line()) + ")";
    if (msg.size() >= suffix.size() && msg.compare(msg.size() - suffix.size(), suffix.size(), suffix) == 0)
      msg.resize(msg.size() - suffix.size());
  }
  return std::string(e.type_name()) + ": " + msg;
}

double us_since(Clock::time_point t0) {
  return std::chrono::duration<double, std::micro>(Clock::now() - t0).count();
}

}  // namespace

int main(int argc, char** argv) {
  std::string dir = "tests/ref/tmpl_fixtures";
  std::string only;
  bool verbose = false;
  int reps = 20;
  for (int i = 1; i < argc; ++i) {
    if (!std::strcmp(argv[i], "--template") && i + 1 < argc)
      only = argv[++i];
    else if (!std::strcmp(argv[i], "--verbose"))
      verbose = true;
    else if (!std::strcmp(argv[i], "--bench-reps") && i + 1 < argc)
      reps = std::atoi(argv[++i]);
    else
      dir = argv[i];
  }

  int total = 0, failed = 0, shown = 0;
  const json::Value* outputs = nullptr;
  auto report = [&](const std::string& what, const Outcome& got, const json::Value& c) {
    ++failed;
    if (shown++ >= 12 && !verbose) return;
    const std::string want = expected_text(c, outputs);
    std::printf("FAIL %s\n", what.c_str());
    if (got.ok == !expects_error(c))
      std::printf("  %s\n", diff_at(got.text, want).c_str());
    else
      std::printf("  got %s: %s\n  want %s: %s\n", got.ok ? "output" : "error", show(got.text).c_str(),
                  expects_error(c) ? "error" : "output", show(want).c_str());
  };

  // ---------------------------------------------------------------- engine snippets
  {
    const json::Value snippets = json::parse(read_file(dir + "/snippets.json"));
    int pass = 0, n = 0;
    for (const json::Value& s : snippets.as_array()) {
      if (!only.empty()) break;
      ++n;
      ++total;
      Outcome got{true, ""};
      try {
        auto t = tmpl::Template::parse(s.get("source")->as_string());
        tmpl::RenderOptions opts;
        std::tm now{};
        now.tm_year = 2026 - 1900, now.tm_mon = 2, now.tm_mday = 15, now.tm_hour = 9, now.tm_min = 5, now.tm_sec = 7;
        opts.now = now;
        got.text = t->render(*s.get("context"), opts);
      } catch (const tmpl::TemplateError& e) {
        got = {false, error_text(e)};
      }
      const bool ok = got.ok == !expects_error(s) && got.text == expected_text(s);
      if (ok)
        ++pass;
      else
        report("snippet " + show(s.get("source")->as_string(), 120), got, s);
    }
    if (only.empty()) std::printf("%-60s %5d/%-5d\n", "[engine snippets]", pass, n);
  }

  // ---------------------------------------------------------------- chat templates
  const json::Value manifest = json::parse(read_file(dir + "/manifest.json"));
  const json::Value fixtures = json::parse(read_file(dir + "/cases.json"));
  const json::Value& convs = *fixtures.get("conversations");
  outputs = fixtures.get("outputs");
  std::tm now{};
  std::sscanf(fixtures.get_string("now", "2026-03-15 09:05:07").c_str(), "%d-%d-%d %d:%d:%d", &now.tm_year,
              &now.tm_mon, &now.tm_mday, &now.tm_hour, &now.tm_min, &now.tm_sec);
  now.tm_year -= 1900;
  now.tm_mon -= 1;
  tmpl::RenderOptions opts;
  opts.now = now;

  std::map<std::string, std::vector<const json::Value*>> by_template;
  for (const json::Value& c : fixtures.get("cases")->as_array())
    by_template[c.get_string("template", "")].push_back(&c);

  std::printf("%-60s %11s %9s %11s %11s\n", "template", "pass/total", "parse_us", "render_us", "max_us");
  double sum_render = 0;
  int sum_render_n = 0;
  for (const json::Value& m : manifest.as_array()) {
    const std::string name = m.get_string("name", "");
    if (!only.empty() && name != only) continue;
    const std::string source = read_file(dir + "/" + m.get_string("file", ""));
    const json::Value& special = *m.get("special_tokens");

    auto t0 = Clock::now();
    std::shared_ptr<const tmpl::Template> t;
    std::string parse_error;
    try {
      t = tmpl::Template::parse(source);
    } catch (const tmpl::TemplateError& e) {
      parse_error = error_text(e);
    }
    const double parse_us = us_since(t0);

    int pass = 0, n = 0;
    std::vector<double> times;
    for (const json::Value* cp : by_template[name]) {
      const json::Value& c = *cp;
      const json::Value& conv = convs[size_t(c.get_int("conv", 0))];
      ++n;
      ++total;
      Outcome got{true, ""};
      if (!t) {
        got = {false, parse_error};
      } else {
        try {
          const auto r0 = Clock::now();
          got.text = tmpl::apply_chat_template(*t, *conv.get("messages"), *conv.get("tools"),
                                               c.get_bool("add_generation_prompt", false), *c.get("kwargs"), special,
                                               opts);
          times.push_back(us_since(r0));
        } catch (const tmpl::TemplateError& e) {
          got = {false, error_text(e)};
        }
      }
      const bool ok = got.ok == !expects_error(c) && got.text == expected_text(c, outputs);
      if (ok)
        ++pass;
      else
        report(name + " :: " + conv.get_string("name", "") + " " + c.get_string("variant", ""), got, c);
    }

    // Steady-state timing: re-render the successful cases.
    double mean = 0, worst = 0;
    if (t && reps > 0) {
      std::vector<double> per_case;
      for (const json::Value* cp : by_template[name]) {
        const json::Value& c = *cp;
        if (expects_error(c)) continue;
        const json::Value& conv = convs[size_t(c.get_int("conv", 0))];
        const auto r0 = Clock::now();
        volatile size_t sink = 0;
        for (int r = 0; r < reps; ++r)
          sink += tmpl::apply_chat_template(*t, *conv.get("messages"), *conv.get("tools"),
                                            c.get_bool("add_generation_prompt", false), *c.get("kwargs"), special, opts)
                      .size();
        const double us = us_since(r0) / reps;
        per_case.push_back(us);
      }
      for (double x : per_case) {
        mean += x;
        worst = std::max(worst, x);
      }
      if (!per_case.empty()) mean /= double(per_case.size());
      sum_render += mean;
      ++sum_render_n;
    }
    std::printf("%-60s %5d/%-5d %9.1f %11.2f %11.2f\n", name.c_str(), pass, n, parse_us, mean, worst);
  }
  if (sum_render_n) std::printf("mean render time over templates: %.2f us\n", sum_render / sum_render_n);
  std::printf("%s: %d/%d cases passed\n", failed ? "FAILED" : "OK", total - failed, total);
  return failed ? 1 : 0;
}
